WITH valid_orders AS (SELECT order_id, member_id, ordered_at, CAST(DATE_TRUNC('month', ordered_at) AS DATE) AS activity_date, CAST(DATE_TRUNC('month', ordered_at) + INTERVAL 1 MONTH - INTERVAL 1 DAY AS DATE) AS month_end, paid_cents - refund_cents AS net_sales_cents FROM {{ ref('orders') }} WHERE status = 'paid' AND paid_cents - refund_cents > 0), qualified_member_month AS (SELECT DISTINCT v.member_id, v.activity_date FROM valid_orders v WHERE EXISTS (SELECT 1 FROM {{ ref('cards') }} c WHERE c.member_id = v.member_id AND c.card_type IN ('悦享年卡', '家庭季卡') AND c.valid_from <= v.month_end AND v.month_end < c.valid_until AND (c.ended_at IS NULL OR v.month_end < c.ended_at))), paid_orders AS (SELECT v.order_id, v.member_id, v.activity_date, v.net_sales_cents FROM valid_orders v JOIN qualified_member_month q ON q.member_id = v.member_id AND q.activity_date = v.activity_date), member_month_counts AS (SELECT member_id, activity_date, COUNT(*) AS monthly_order_count FROM paid_orders GROUP BY member_id, activity_date) SELECT p.order_id, p.member_id, p.activity_date, p.net_sales_cents, c.monthly_order_count FROM paid_orders p JOIN member_month_counts c ON c.member_id = p.member_id AND c.activity_date = p.activity_date